import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {viewerRuntimeFingerprint, verifyServedViewerClient} from '/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad/scripts/bench/viewer-memory/fingerprint.mjs';
export const repo='/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad';
export const origin='http://127.0.0.1:3276';
export async function proof(){
 const runtime=viewerRuntimeFingerprint();
 if(runtime.source!=='e375623ab5dddd082e6113635b2fab861943547accc11c97d390f7e59cbeb77a'||runtime.builtClient!=='5cf47abe1c444dbfa742acadb51486126ae634d6ebf6e8895baf6646b3e19cc4')throw new Error('Integrated frozen source or client differs');
 const client=await verifyServedViewerClient(origin),workers=[];
 for(const name of fs.readdirSync(path.join(client.dist,'assets')).filter(n=>/worker.*\.js$/i.test(n))){
  const r=await fetch(origin+'/assets/'+name,{cache:'no-store',signal:AbortSignal.timeout(5000)});
  const bytes=Buffer.from(await r.arrayBuffer());
  if(!r.ok||!bytes.equals(fs.readFileSync(path.join(client.dist,'assets',name))))throw new Error('Worker bytes differ: '+name);
  workers.push({path:'/assets/'+name,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')});
 }
 return {at:new Date().toISOString(),commit:'8971f760d',runtime,client,workers,server:JSON.parse(fs.readFileSync('/private/tmp/cadgen-performance-20260910/integrated-medium-server-proof.json'))};
}

