import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {createRequire} from 'node:module';
import {execFileSync} from 'node:child_process';
import {proof,repo,origin} from './integrated-medium-proof.mjs';
import {installWorkerProbe} from '/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad/scripts/bench/viewer-memory/worker-probe.mjs';
import {processMemoryFromPs,mergeProcessPeak} from '/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad/scripts/bench/viewer-memory/adaptive-support.mjs';
const require=createRequire(import.meta.url),{chromium}=require('/Users/jakefitzgerald/robots/text-to-cad/apps/viewer/node_modules/playwright');
export const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
export function installInspection(){
 const ids=new WeakMap();let counter=0;
 const id=o=>{if(!o||typeof o!=='object')return null;if(!ids.has(o))ids.set(o,++counter);return ids.get(o)};
 const find=()=>{
  let el=document.querySelector('canvas'),f;
  while(el&&!f){const key=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));if(key)f=el[key];el=el.parentElement}
  for(let i=0;f&&i<150;i++,f=f.return){const p=f.memoizedProps;if(p&&Array.isArray(p.selectedPartIds)&&Array.isArray(p.selectedReferenceIds)&&Object.hasOwn(p,'selectorRuntime')){
   let runtime=null;for(let h=f.memoizedState,n=0;h&&n<500;h=h.next,n++){const v=h.memoizedState?.current;if(v?.renderer&&v?.modelGroup){runtime=v;break}}
   return {p,runtime};
  }}return{};
 };
 window.__ownershipInspect=()=>{
  const {p,runtime}=find(),selector=p?.selectorRuntime,rows=runtime?.displayRecords||[];
  const refs=selector?.references||[];
  const columns=selector?.proxy?.faceRunColumns||[],runs=selector?.proxy?.faceRuns;
  const sums=new Map();for(let n=0; n<(runs?.length||0); n+=columns.length){const row=runs[n+columns.indexOf('occurrenceRow')], count=runs[n+columns.indexOf('triangleCount')];sums.set(row,(sums.get(row)||0)+count)}
  const partRows=(p?.meshData?.parts||[]).map(x=>({id:x.id,cid:x.componentId,level:x.sourceMesh?.lodLevel,mesh:id(x.sourceMesh),triangles:Math.floor((x.sourceMesh?.indices?.length||0)/3)}));
  return {at:performance.now(),selection:p?{selectedPartIds:p.selectedPartIds.slice(),selectedReferenceIds:p.selectedReferenceIds.slice(),hiddenPartIds:p.hiddenPartIds.slice()}:null,
   source:id(p?.meshData),actualSource:id(runtime?.cadScene?.source),sceneRecords:rows.length,
   partRows,recordRows:rows.map(r=>({id:r.partId,mesh:id(r.sourcePart?.sourceMesh),visible:r.mesh?.visible,selected:r.selected,materialVisible:r.material?.visible})),
   selectors:selector?{id:id(selector),stepHash:selector.stepHash,occurrences:selector.occurrences?.map(r=>r.id),occurrenceIds:[...(selector.occurrenceIdByRowIndex||[])],faceRunColumns:columns,faceRunCount:runs?runs.length/columns.length:0,faceCoverage:[...sums].map(([row,triangles])=>({id:selector.occurrenceIdByRowIndex.get(row),triangles})),references:refs.slice(0,6).map(x=>({id:x.id,partId:x.partId,type:x.selectorType,selector:x.normalizedSelector}))}:null,
   adoption:window.__cadLodSceneAdoption?.(),lod:window.__cadViewportLod?.(),memory:window.__cadViewerMemoryPolicySnapshot?.(),probe:window.__cadRenderMemoryProbe?.(),workers:{...window.__cadWorkerProbe},meshCost:window.__cadMeshCost,
   zoom:document.querySelector('input[aria-label="Zoom level percent"]')?.value,alerts:[...document.querySelectorAll('[role="alert"]')].map(x=>x.textContent),
  };
 };
 window.__ownershipRuntime=find;
}
export async function runCase(name,fn,{file='planetary.step',timeoutMs=40000,init}={}){
 const out=path.join(repo,'scripts/bench/cadgen-performance/results',name+'.json');if(fs.existsSync(out))throw new Error('Refusing to overwrite '+out);
 const report={startedAt:new Date().toISOString(),qualification:'Integrated committed 8971f760d functional private-browser test. No performance isolation or speedup claim; no allocation sampling or forced GC. Only numeric counters and short IDs are retained.',errors:[],samples:[],assertions:{},peakRss:{}};
 const profile=fs.mkdtempSync(path.join(os.tmpdir(),'viewer-medium-ownership-'));let context,page,watchdog,sampler;
 try{
  report.beforeProof=await proof();
  context=await chromium.launchPersistentContext(profile,{headless:true,viewport:{width:1400,height:900},args:['--use-angle=metal','--enable-precise-memory-info']});
  watchdog=setTimeout(()=>{report.guard='40-second functional deadline';context.close().catch(()=>{})},timeoutMs);
  sampler=setInterval(()=>{try{const r=processMemoryFromPs(execFileSync('/bin/ps',['-axww','-o','pid=,ppid=,rss=,args='],{encoding:'utf8'}),profile);mergeProcessPeak(report.peakRss,r);if(r.renderer?.largestPidBytes>2048*1024*1024){report.guard='2 GiB renderer bound';context.close().catch(()=>{})}}catch{}},500);
  page=context.pages()[0]||await context.newPage();await page.addInitScript(installWorkerProbe);await page.addInitScript(installInspection);if(init)await page.addInitScript(init);
  page.on('pageerror',e=>report.errors.push(String(e)));page.setDefaultTimeout(5000);
  const sample=async label=>{const s={label,...await page.evaluate(()=>window.__ownershipInspect())};report.samples.push(s);return s};
  const settled=async(label,occurrences)=>{let last;for(let n=0;n<90;n++){last=await sample(label);if(last.sceneRecords===occurrences&&last.adoption?.pending===0&&!last.lod?.busy&&!last.lod?.pendingEvaluation&&last.lod?.qualitySettled&&last.memory?.reservationCount===0)return last;await pause(150)}throw new Error('Not settled: '+label)};
  const zoom=async value=>{const z=page.getByLabel('Zoom level percent',{exact:true});await z.fill(String(value));await z.press('Enter')};
  await page.goto(origin+'/?file='+encodeURIComponent(file),{waitUntil:'domcontentloaded',timeout:15000});
  await fn({report,page,context,sample,settled,zoom});
  report.afterProof=await proof();report.assertions.sourceAndClientStable=true;report.assertions.noGuard=!report.guard;
  report.outcome=Object.values(report.assertions).every(x=>x===true)?'passed':'failed';
 }catch(e){report.outcome='failed';report.error=String(e.stack||e)}finally{
  clearTimeout(watchdog);clearInterval(sampler);await context?.close().catch(()=>{});report.finishedAt=new Date().toISOString();
  fs.writeFileSync(out,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({outcome:report.outcome,error:report.error,assertions:report.assertions,out}));
 }
 return report;
}
export {repo,origin};

