import path from 'node:path';
import {runCase,pause,repo} from './integrated-medium-common.mjs';
await runCase('viewer-nine-selection-ownership-integrated-v2-20260910',async({report:r,page,sample,settled,zoom})=>{
 r.initial=await settled('initial',9);
 const part=page.getByLabel('Component carrier_plate',{exact:true});
 await part.getByText('carrier_plate',{exact:true}).click();await pause(100);
 r.selected=await sample('part-selected');
 await page.getByRole('button',{name:'Expand carrier_plate',exact:true}).click();
 await page.waitForFunction(()=>window.__ownershipInspect().selectors?.references.length>0);
 r.treeRows=await page.getByRole('treeitem').evaluateAll(rows=>rows.slice(0,15).map(x=>({label:x.getAttribute('aria-label'),id:x.dataset.stepTreeNodeId,text:x.textContent.slice(0,100)})));
 console.log(JSON.stringify({phase:'topology-rows',rows:r.treeRows}));
 const face=page.getByRole('treeitem').filter({hasText:/^f1\b/}).first();
 if(await face.count())await face.click();
 else {
  const label=r.treeRows.find(x=>/^Face /i.test(x.label||''))?.label;
  if(!label)throw new Error('Face row could not be identified from actual tree');
  await page.getByLabel(label,{exact:true}).click();
 }
 await pause(150);r.faceSelected=await sample('face-selected');
 const refs=r.faceSelected.selection?.selectedReferenceIds||[];
 if(!refs.length)throw new Error('No actual face selection');
 await zoom(800);r.near=await settled('near',9);await zoom(100);r.returned=await settled('returned',9);
 r.assertions.selectorsMatchDisplayedTriangles=[r.faceSelected,r.near,r.returned].every(s=>s.selectors.faceCoverage.length>0&&s.selectors.faceCoverage.every(f=>s.partRows.find(p=>p.id===f.id)?.triangles===f.triangles));
 r.assertions.selectedReferencePersists=[r.near,r.returned].every(s=>JSON.stringify(s.selection.selectedReferenceIds)===JSON.stringify(refs));
 r.assertions.allOccurrencesRemain=[r.initial,r.near,r.returned].every(s=>s.sceneRecords===9);
 r.assertions.actualAdoptionSettled=r.returned.adoption.pending===0&&r.returned.memory.reservationCount===0;
 r.selectedScreenshot=path.join(repo,'models/tmp/viewer-matched-nine-after/ownership-integrated-selected-v2.png');await page.screenshot({path:r.selectedScreenshot});
 await part.getByText('carrier_plate',{exact:true}).click({button:'right'});await page.getByRole('menuitem',{name:'Hide',exact:true}).click();await pause(100);r.hidden=await sample('hidden');
 r.assertions.hideWorks=r.hidden.selection.hiddenPartIds.includes('o1.1');
 await part.getByText('carrier_plate',{exact:true}).click({button:'right'});r.hideMenu=await page.getByRole('menuitem').allTextContents();
 const show=page.getByRole('menuitem',{name:'Reveal',exact:true});if(await show.count())await show.click();else throw new Error('Reveal action not available');
 await pause(100);r.shown=await sample('shown');r.assertions.showWorks=!r.shown.selection.hiddenPartIds.includes('o1.1');r.assertions.zeroErrors=r.errors.length===0;
});

