import {runCase,pause} from './integrated-medium-common.mjs';
function installSelectorFailure(){
 const Original=window.Worker;
 const state={armed:false,throws:0,requests:[]};window.__selectorFault=state;
 window.Worker=class extends Original{
  postMessage(message,...rest){
   if(state.armed&&message?.type==='loadSurf'&&message.capabilities?.selectors){
    state.armed=false;state.throws++;
    state.requests.push({id:message.id,url:String(message.url),capabilities:{...message.capabilities},tessellation:{...message.tessellation},cachedBytes:message.cachedEntry?.byteLength||0,before:window.__ownershipInspect()});
    queueMicrotask(()=>this.dispatchEvent(new MessageEvent('message',{data:{id:message.id,ok:false,error:{name:'Error',message:'Injected required selector load failure'}}})));
    return;
   }
   return super.postMessage(message,...rest);
  }
 };
 window.__restoreSelectorFault=()=>{window.Worker=Original};
}
await runCase('viewer-nine-selector-failure-ownership-integrated-v2-20260910',async({report:r,page,sample,settled,zoom})=>{
 await settled('initial',9);
 await page.getByRole('button',{name:'Expand carrier_plate',exact:true}).click();
 await page.waitForFunction(()=>window.__ownershipInspect().selectors?.references.length>0);
 const face=page.getByRole('treeitem').filter({hasText:/^Face f1$/});await face.click();
 await pause(250);r.before=await settled('selected-before',9);
 await page.evaluate(()=>{window.__selectorFault.armed=true});
 await zoom(800);
 let s;
 for(let i=0;i<110;i++){
  s=await sample('failure-drain');const n=await page.evaluate(()=>window.__selectorFault.throws);
  if(n>0&&!s.lod.busy&&!s.lod.pendingEvaluation&&s.adoption.pending===0&&s.memory.reservationCount===0)break;
  await pause(100);
 }
 r.after=s;r.injection=await page.evaluate(()=>window.__selectorFault);
 const target=r.before.partRows.find(x=>x.id==='o1.1'),after=r.after.partRows.find(x=>x.id==='o1.1');
 r.assertions.actualRequiredSelectorFailure=r.injection.throws===1&&r.injection.requests[0]?.capabilities.selectors===true;
 r.assertions.failedTargetNotPromoted=r.after.lod.unmetTargets.some(x=>x.cid===target.cid&&x.targetLevel===3&&x.currentLevel<3&&x.reason==='load-failed')&&after.level<3;
 r.intermediateFallback={beforeLevel:target.level,afterLevel:after.level,qualification:'A failed L3 request may use the existing policy’s successful intermediate L2 fallback. Only promotion of the failed concrete target is prohibited.'};
 r.assertions.noRestorationNeeded=r.after.adoption.restored===r.before.adoption.restored;
 r.assertions.faceSelectionPersists=JSON.stringify(r.before.selection.selectedReferenceIds)===JSON.stringify(r.after.selection.selectedReferenceIds);
 r.assertions.selectorPairPreserved=r.after.selectors.faceCoverage.every(f=>r.after.partRows.find(p=>p.id===f.id)?.triangles===f.triangles);
 r.assertions.completeViewPreserved=r.after.sceneRecords===9;
 r.assertions.leaseDrained=r.after.memory.reservationCount===0&&r.after.adoption.pending===0;
 r.assertions.failureParked=r.after.lod.unmetTargets.some(x=>x.cid===target.cid&&x.reason==='load-failed');
 await pause(500);r.parked=await sample('parked');r.assertions.noBusyLoop=!r.parked.lod.busy&&r.parked.adoption.requested===r.after.adoption.requested;
 r.assertions.zeroErrors=r.errors.length===0;
 await page.evaluate(()=>window.__restoreSelectorFault());
},{init:installSelectorFailure});

