import path from 'node:path';
import {runCase,pause,repo} from './integrated-medium-common.mjs';
const mode=process.argv[2]||'restore';
await runCase(`viewer-repeated24-${mode}-ownership-integrated-20260910`,async({report:r,page,sample,settled,zoom})=>{
 r.initial=await settled('initial',24);
 await page.getByLabel('Component box_1',{exact:true}).getByText('box_1',{exact:true}).click();
 r.selected=await sample('selected');
 r.injection=await page.evaluate(async mode=>{
  const vendor=[...document.querySelectorAll('link[href*="vendor-three-"]')][0]?.href;
  if(!vendor)throw new Error('No served Three vendor URL');
  const exports=await import(vendor), pair=Object.entries(exports).find(([,v])=>v?.MeshPhysicalMaterial&&v?.Material);
  if(!pair)throw new Error('No actual Three namespace export');
  const [exportKey,THREE]=pair,actual=window.__ownershipRuntime().runtime;
  if(!actual?.cadScene||actual.displayRecords[0].material.constructor!==THREE.MeshPhysicalMaterial)throw new Error('Three namespace differs from displayed materials');
  const original=THREE.MeshPhysicalMaterial.prototype.setValues;
  const oldGeometry=new WeakSet(actual.displayRecords.map(r=>r.geometry));
  const state={mode,calls:0,throws:0,events:[],restorationSeen:false};window.__ownershipFault=state;
  const inspect=()=>{
   const rt=window.__ownershipRuntime().runtime;
   return {at:performance.now(),source:window.__ownershipInspect().actualSource,
    attached:rt?.cadScene?.modelGroup?.children.filter(o=>o.userData?.partId).map(o=>({id:o.userData.partId,newGeometry:!!o.geometry&&!oldGeometry.has(o.geometry)}))||[],
    adoption:window.__cadLodSceneAdoption?.(),memory:window.__cadViewerMemoryPolicySnapshot?.()};
  };
  THREE.MeshPhysicalMaterial.prototype.setValues=function(values){
   if(this.isMeshPhysicalMaterial&&values&&typeof values==='object'){
    state.calls++;
    const phase=window.__cadLodSceneAdoption?.().phase;
    const fail=(state.throws===0&&state.calls===2)||(mode==='fatal'&&state.throws===1&&phase==='restoring');
    if(fail){state.throws++;state.events.push(inspect());throw new Error('Injected bounded '+mode+' material failure '+state.throws)}
   }
   return original.apply(this,arguments);
  };
  window.__restoreOwnershipFault=()=>{THREE.MeshPhysicalMaterial.prototype.setValues=original};
  return {vendor,exportKey,revision:THREE.REVISION,kind:'Actual MeshPhysicalMaterial.setValues failure; original restored before browser close'};
 },mode);
 await zoom(800);
 let last;
 for(let i=0;i<120;i++){
  last=await sample('fault-drain');
  const fault=await page.evaluate(()=>({...window.__ownershipFault}));
  if(fault.throws>0&&last.adoption?.pending===0&&!last.lod?.busy&&!last.lod?.pendingEvaluation){r.fault=fault;break}
  await pause(100);
 }
 r.after=last;r.fault ||= await page.evaluate(()=>({...window.__ownershipFault}));
 r.assertions.injected=r.fault.throws===(mode==='fatal'?2:1);
 r.assertions.partialNewGeometryAttached=r.fault.events[0]?.attached.some(x=>x.newGeometry)===true;
 r.assertions.leaseHeldAtFailure=r.fault.events.every(x=>x.memory.reservationCount>0);
 r.assertions.finalLeaseReleased=last.memory?.reservationCount===0&&last.adoption?.pending===0;
 if(mode==='restore'){
  r.assertions.restoredOutcome=last.adoption?.restored===1;
  r.assertions.completeViewRestored=last.sceneRecords===24;
  r.assertions.selectionPersisted=JSON.stringify(last.selection?.selectedPartIds)===JSON.stringify(r.selected.selection?.selectedPartIds);
  const sourceAtFailure=r.fault.events[0].source;
  r.assertions.failedSourceNotDisplayed=last.actualSource!==sourceAtFailure;
  r.assertions.failedTargetNotPromoted=(last.lod?.unmetTargets||[]).some(x=>x.reason==='adoption-refused');
 }else{
  r.assertions.fatalStopsScheduler=last.lod?.sceneFailed===true&&last.sceneRecords===0;
  r.assertions.qualityUnmet=last.lod?.qualitySettled===false&&(last.lod?.unmetTargets||[]).length>0;
  const requested=last.adoption?.requested;await pause(600);r.parked=await sample('fatal-parked');
  r.assertions.noRetryLoop=r.parked.adoption.requested===requested&&r.parked.lod.sceneFailed;
 }
 r.screenshot=path.join(repo,'models/tmp/viewer-matched-nine-after',`ownership-integrated-${mode}.png`);await page.screenshot({path:r.screenshot});
 await page.evaluate(()=>window.__restoreOwnershipFault?.());
 r.assertions.noUnexpectedPageErrors=r.errors.length===0;
},{file:'repeated24.step'});

