import {runCase,pause} from './integrated-medium-common.mjs';
function installDelayedReply(){
 const Original=window.Worker,state={armed:false,captured:false,delivered:0};window.__replacementFault=state;
 window.Worker=class extends Original{
  addEventListener(type,listener,options){
   if(type!=='message'||typeof listener!=='function')return super.addEventListener(type,listener,options);
   const wrapper=event=>{
    if(event.data?.id===this.__heldId){
     if(!state.captured){state.captured=true;state.before=window.__ownershipInspect();state.id=event.data.id;state.ok=event.data.ok;state.capturedAt=performance.now()}
     setTimeout(()=>{state.delivered++;state.deliveredAt=performance.now();listener.call(this,event)},1500);
    }else listener.call(this,event);
   };
   return super.addEventListener(type,wrapper,options);
  }
  postMessage(message,...rest){if(state.armed&&message?.type==='loadSurf'){state.armed=false;this.__heldId=message.id;state.request={url:String(message.url),tessellation:{...message.tessellation},capabilities:{...message.capabilities}}}return super.postMessage(message,...rest)}
 };
 window.__restoreReplacementFault=()=>{window.Worker=Original};
}
